using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using System.Linq;
public static class BrowserProjectPort { public static void Prepare(){var scene=EditorSceneManager.OpenScene("Assets/Scenes/MainScene.unity");if(!scene.GetRootGameObjects().Any(g=>g.name=="Desktop Explorer")){foreach(var g in scene.GetRootGameObjects())if(g.name.Contains("OVR")||PrefabUtility.GetPrefabAssetType(g)==PrefabAssetType.MissingAsset)Object.DestroyImmediate(g);var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Imports/Standard Assets/Characters/FirstPersonCharacter/Prefabs/FPSController.prefab");var player=(GameObject)PrefabUtility.InstantiatePrefab(prefab);player.name="Desktop Explorer";player.transform.position=new Vector3(26.12687f,8.965f,30.872467f);player.AddComponent<PlayerColision>();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);}}}